def transform(grid):
    out = [row[:] for row in grid]
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    top = min(r for r, c in cells)
    bottom = max(r for r, c in cells)
    left = min(c for r, c in cells)
    right = max(c for r, c in cells)

    hmid = (top + bottom) / 2
    vmid = (left + right) / 2
    colors = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color == 0 or color == 5:
                continue
            qr = 0 if r < hmid else 1
            qc = 0 if c < vmid else 1
            colors[(qr, qc)] = color
            colors[(1 - qr, 1 - qc)] = color

    rmid = (top + bottom + 1) // 2
    cmid = (left + right + 1) // 2
    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            qr = 0 if r < rmid else 1
            qc = 0 if c < cmid else 1
            if (qr, qc) in colors:
                out[r][c] = colors[(qr, qc)]
    return out
